import { editAccountSettings } from '~/client';
import type { EditAccountSettingsResponse, EditAccountSettingsRequest } from '~/client';

export const useEditUserSettings = defineMutation(() => {
  const {
    mutateAsync: editUserSettings,
    asyncStatus,
    error,
    status,
  } = useMutation({
    mutation: (editTimezoneForm: EditAccountSettingsRequest): Promise<EditAccountSettingsResponse> =>
      editAccountSettings({
        composable: '$fetch',
        body: editTimezoneForm,
      }),
    onSuccess: async () => {
      const { getSession } = useAuth();
      await getSession();
      await navigateTo({ name: 'account' });
      showToastSuccess('Settings updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    status,
    error,
    editUserSettings,
    isEditingUserSettings: computed(() => asyncStatus.value === 'loading'),
  };
});
