<template>
  <section class="flex flex-col gap-10">
    <h1 class="font-semibold text-3xl">My Account</h1>

    <section class="flex flex-col w-full gap-4">
      <GoBackButton subject="account" :fallback-to="{ name: 'account' }" />
      <Card class="w-full flex flex-col max-w-[700px] justify-center self-center">
        <CardHeader>
          <CardTitle class="p-0 text-lg font-semibold">Edit Settings</CardTitle>
        </CardHeader>
        <CardContent>
          <form
            id="edit-timezone-form"
            class="self-center flex flex-col gap-6 flex-auto w-full justify-center max-w-[700px] max-lg:px-0"
            @submit="onSubmit"
          >
            <FormItemWrapper name="time_zone" label="Timezone">
              <template #default="{ slots }">
                <KitFormsSelect
                  id="time_zone"
                  :component-field="slots.componentField"
                  :items="timezones"
                  :disabled="isLoading"
                  @vue:mounted="() => slots.setValue(timezone, false)"
                />
              </template>
            </FormItemWrapper>
            <Button type="submit" form="edit-timezone-form" :loading="isEditingUserSettings">Save New Timezone</Button>
          </form>
        </CardContent>
      </Card>
    </section>
  </section>
</template>

<script setup lang="ts">
import { useSelectorTimezoneList } from '~/queries/selectors/timezones';
import { useEditUserSettings } from '~/mutations/account/editUserSettings';
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';

const { timezones, isLoading } = useSelectorTimezoneList();

const { timezone } = useUserRole();

const formSchema = toTypedSchema(
  z.object({
    time_zone: z.string().nonempty({ message: 'Timezone is required' }),
  })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const { editUserSettings, isEditingUserSettings } = useEditUserSettings();

const onSubmit = handleSubmit(async (values) => {
  await editUserSettings(values).catch((error) => console.error('Error updating timezone:', error));
});
</script>

<style scoped lang="scss"></style>
